sp_widget.client_script:
api.controller = function($scope, $timeout) {
  var c = this;

  c.isOpen = false;
  c.message = "";
  c.messages = [];
  c.sending = false;

  c.sendMessage = function() {
    var text = (c.message || "").trim();

    if (!text || c.sending) return;

    c.messages.push({
      type: "user",
      text: text
    });

    c.message = "";
    c.sending = true;

    c.server.get({
      message: text
    }).then(function(response) {
      var result = response.data || {};

      c.messages.push({
        type: "assistant",
        text: result.reply || "I couldn't prepare a response. Please try again.",
        links: result.links || [],
        results: result.results || []
      });

      scrollToBottom();
    }, function() {
      c.messages.push({
        type: "assistant",
        text: "Sorry, I couldn't reach CampusOps just now. Please try again.",
        links: [],
        results: []
      });

      scrollToBottom();
    }).finally(function() {
      c.sending = false;
      scrollToBottom();
    });

    scrollToBottom();
  };

  function scrollToBottom() {
    $timeout(function() {
      var panel = document.getElementById("co-chat-messages");

      if (panel) {
        panel.scrollTop = panel.scrollHeight;
      }
    }, 100);
  }
};

sp_widget.css:
/* CampusOps assistant */
.co-chat-widget {
  font-family: inherit;
  color: #30234f;
}

/* Floating launcher */
.co-chat-launcher {
  position: fixed !important;
  right: 24px !important;
  bottom: 24px !important;
  top: auto !important;
  left: auto !important;
  z-index: 2147483000 !important;

  width: 58px;
  height: 58px;
  padding: 0;
  border: 1px solid rgba(255,255,255,.7);
  border-radius: 50%;
  background: #8062c7;
  color: #fff;
  box-shadow: 0 6px 22px rgba(61,43,99,.25);
  cursor: pointer;

  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform .2s ease, box-shadow .2s ease;
}

.co-chat-launcher:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 28px rgba(61,43,99,.3);
}

.co-launcher-mark {
  font-size: 23px;
  font-weight: 700;
}

/* Floating chat panel */
.co-chat-panel {
  position: fixed !important;
  right: 24px !important;
  bottom: 94px !important;
  top: auto !important;
  left: auto !important;
  z-index: 2147483000 !important;

  width: 370px;
  height: min(540px, calc(100vh - 125px));
  min-height: 300px;
  max-height: calc(100vh - 125px);

  display: flex;
  flex-direction: column;
  overflow: hidden;

  background: #fff;
  border: 1px solid #e5d9fb;
  border-radius: 18px;
  box-shadow: 0 14px 50px rgba(45,32,75,.24);
  animation: co-chat-appear .18s ease-out;
}

@keyframes co-chat-appear {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Header */
.co-chat-header {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 15px 16px;
  background: linear-gradient(110deg,#f0e7ff,#fceefa);
  border-bottom: 1px solid #e6dafa;
}

.co-chat-brand {
  display: flex;
  align-items: center;
  gap: 11px;
}

.co-chat-logo {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border-radius: 12px;
  background: #8062c7;
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 17px;
  font-weight: 700;
}

.co-chat-header h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 700;
  color: #30234f;
}

.co-chat-header p {
  margin: 0;
  font-size: 11px;
  color: #796a96;
}

.co-chat-close {
  flex: 0 0 30px;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #68528f;
  font-size: 24px;
  cursor: pointer;
}

.co-chat-close:hover {
  background: rgba(128,98,199,.12);
}

/* Conversation: scroll only inside this area */
.co-chat-messages {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: #c6b4ed transparent;

  padding: 16px 13px;
  background: #fdfbff;
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.co-chat-messages::-webkit-scrollbar {
  width: 5px;
}

.co-chat-messages::-webkit-scrollbar-track {
  background: transparent;
}

.co-chat-messages::-webkit-scrollbar-thumb {
  background: #c6b4ed;
  border-radius: 10px;
}

.co-chat-welcome,
.co-chat-answer {
  align-self: flex-start;
  max-width: 88%;
  padding: 11px 12px;
  border: 1px solid #e6dafa;
  border-radius: 13px 13px 13px 4px;
  background: #f3edff;
  color: #392958;
  font-size: 12px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.co-chat-message {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.co-chat-user {
  align-self: flex-end;
  max-width: 85%;
  padding: 10px 13px;
  border-radius: 13px 13px 4px 13px;
  background: #8062c7;
  color: #fff;
  font-size: 12px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.co-chat-answer p {
  margin: 0 0 7px;
}

.co-chat-link {
  display: block;
  margin-top: 7px;
  color: #6849b4;
  font-size: 12px;
  text-decoration: none;
}

.co-chat-link:hover {
  text-decoration: underline;
}

.co-chat-result {
  display: block;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid #e5d9fb;
  border-radius: 9px;
  background: #fff;
  color: #35254f;
  text-decoration: none;
}

.co-chat-result:hover {
  border-color: #b7a0ed;
  background: #faf7ff;
}

.co-chat-result strong,
.co-chat-result small {
  display: block;
}

.co-chat-result strong {
  font-size: 12px;
}

.co-chat-result small {
  margin-top: 3px;
  color: #806f9b;
  font-size: 10px;
}

.co-chat-typing {
  align-self: flex-start;
  color: #806f9b;
  font-size: 11px;
}

/* Input stays at the bottom of the panel */
.co-chat-input-row {
  flex: 0 0 auto;
  display: flex;
  gap: 8px;
  padding: 11px;
  background: #fff;
  border-top: 1px solid #eee6fa;
}

.co-chat-input-row input {
  flex: 1 1 auto;
  min-width: 0;
  height: 40px;
  padding: 0 11px;
  border: 1px solid #ddcff8;
  border-radius: 10px;
  outline: none;
  background: #fdfbff;
  color: #30234f;
  font-family: inherit;
  font-size: 12px;
}

.co-chat-input-row input:focus {
  border-color: #8062c7;
  box-shadow: 0 0 0 2px rgba(128,98,199,.1);
}

.co-chat-input-row button {
  flex: 0 0 auto;
  padding: 0 13px;
  border: 0;
  border-radius: 10px;
  background: #8062c7;
  color: #fff;
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.co-chat-input-row button:disabled {
  opacity: .55;
  cursor: not-allowed;
}

/* Mobile layout */
@media (max-width: 480px) {
  .co-chat-launcher {
    right: 16px !important;
    bottom: 16px !important;
  }

  .co-chat-panel {
    right: 10px !important;
    bottom: 84px !important;
    width: calc(100vw - 20px);
    height: min(600px, calc(100vh - 105px));
    min-height: 280px;
    max-height: calc(100vh - 105px);
  }
}

/* Short screens */
@media (max-height: 420px) {
  .co-chat-panel {
    height: calc(100vh - 100px);
    min-height: 220px;
    max-height: calc(100vh - 100px);
  }
}


/* Force the assistant to float independently of page content */
.co-chat-widget {
  position: static !important;
  width: 0 !important;
  height: 0 !important;
  overflow: visible !important;
  z-index: 2147483000 !important;
}

.co-chat-launcher {
  position: fixed !important;
  right: 24px !important;
  bottom: 24px !important;
  top: auto !important;
  left: auto !important;
  z-index: 2147483000 !important;
}

.co-chat-panel {
  position: fixed !important;
  right: 24px !important;
  bottom: 94px !important;
  top: auto !important;
  left: auto !important;
  z-index: 2147483000 !important;
  margin: 0 !important;
}

@media (max-width: 480px) {
  .co-chat-panel {
    right: 10px !important;
    bottom: 84px !important;
    width: calc(100vw - 20px) !important;
  }
}



/* CampusOps assistant — wider, softer floating panel */
.co-chat-panel {
  width: 420px !important;
  height: min(600px, calc(100vh - 120px)) !important;

  right: 24px !important;
  bottom: 94px !important;

  border: 1px solid #e5d9fb !important;
  border-radius: 24px !important;

  background: linear-gradient(
    145deg,
    #ffffff 0%,
    #fcf9ff 55%,
    #f8f2ff 100%
  ) !important;

  box-shadow:
    0 18px 55px rgba(61, 43, 99, 0.18),
    0 4px 14px rgba(128, 98, 199, 0.08) !important;

  overflow: hidden !important;
}

/* Softer rounded header */
.co-chat-header {
  border-radius: 23px 23px 0 0 !important;
  padding: 17px 18px !important;
  background: linear-gradient(
    110deg,
    #eee5ff,
    #fceeff
  ) !important;
}

/* Round the bottom input area */
.co-chat-input-row {
  border-radius: 0 0 23px 23px !important;
  padding: 13px !important;
  background: rgba(255, 255, 255, 0.96) !important;
}

.co-chat-input-row input {
  height: 44px !important;
  border-radius: 13px !important;
}

.co-chat-input-row button {
  border-radius: 13px !important;
  min-width: 64px;
}

/* Keep the launcher consistent with the panel */
.co-chat-launcher {
  border-radius: 50% !important;
}

/* Responsive layout */
@media (max-width: 480px) {
  .co-chat-panel {
    width: calc(100vw - 20px) !important;
    height: min(620px, calc(100vh - 100px)) !important;
    right: 10px !important;
    bottom: 84px !important;
    border-radius: 22px !important;
  }

  .co-chat-header {
    border-radius: 21px 21px 0 0 !important;
  }
}


.co-launcher-icon {
  width: 30px;
  height: 30px;
  display: block;
}

sp_widget.script:
(function() {
  data.firstName = gs.getUser().getFirstName() || "there";
  data.reply = "";
  data.links = [];
  data.results = [];

  var userId = gs.getUserID();
  var message = "";

  if (input && input.message) {
    message = (input.message + "").toLowerCase().trim();
  }

  function addLink(label, url) {
    data.links.push({
      label: label,
      url: url
    });
  }

  function formatDate(value) {
    if (!value) return "Not set";

    var parts = value.substring(0, 10).split("-");
    if (parts.length !== 3) return value;

    var months = [
      "Jan", "Feb", "Mar", "Apr", "May", "Jun",
      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ];

    var month = parseInt(parts[1], 10) - 1;
    var day = parseInt(parts[2], 10);

    if (month < 0 || month > 11) return value;

    return day + " " + months[month] + " " + parts[0];
  }

  // Search available campus resources.
  function showAssets(searchTerm) {
    var asset = new GlideRecord("u_campus_asset");
    asset.addQuery("u_status", "available");

    if (searchTerm) {
      var condition = asset.addQuery(
        "u_asset_name", "CONTAINS", searchTerm
      );

      condition.addOrCondition(
        "u_asset_id", "CONTAINS", searchTerm
      );

      condition.addOrCondition(
        "u_asset_type", "CONTAINS", searchTerm
      );

      condition.addOrCondition(
        "u_location", "CONTAINS", searchTerm
      );
    }

    asset.orderBy("u_asset_name");
    asset.setLimit(5);
    asset.query();

    while (asset.next()) {
      data.results.push({
        name: asset.getDisplayValue("u_asset_name") ||
              "Campus resource",

        detail:
          (asset.getDisplayValue("u_asset_type") || "Resource") +
          " · " +
          (asset.getDisplayValue("u_location") ||
           "Location not listed"),

        url: "/sp?id=asset_details&sys_id=" +
             asset.getUniqueValue()
      });
    }

    if (data.results.length > 0) {
      data.reply = searchTerm
        ? "Here are the available resources matching your search:"
        : "Here are some resources currently marked available.";
    } else {
      data.reply = searchTerm
        ? "I couldn't find an available resource matching that search. Try another name, type, or location."
        : "No available resources were found right now. Please check the catalogue again later.";
    }

    addLink("Browse all assets", "/sp?id=browse_assets");
  }

  // Show the signed-in student's active rentals.
  function showRentals(dueOnly) {
    var rental = new GlideRecord("u_student_rental");
    rental.addQuery("u_student", userId);
    rental.addQuery("u_status", "active");
    rental.orderBy("u_due_date");
    rental.setLimit(50);
    rental.query();

    var now = new GlideDateTime().getNumericValue();
    var dayMs = 86400000;
    var overdueCount = 0;
    var dueSoonCount = 0;
    var shownCount = 0;

    while (rental.next()) {
      var dueValue = rental.getValue("u_due_date");
      var daysLeft = null;

      if (dueValue) {
        daysLeft = Math.ceil(
          (new GlideDateTime(dueValue).getNumericValue() - now) /
          dayMs
        );
      }

      var overdue = daysLeft !== null && daysLeft < 0;
      var dueSoon = daysLeft !== null && daysLeft <= 2;

      if (overdue) {
        overdueCount++;
      } else if (dueSoon) {
        dueSoonCount++;
      }

      if (dueOnly && !dueSoon) {
        continue;
      }

      var dueText = dueValue
        ? formatDate(dueValue)
        : "Due date not set";

      var detail;

      if (overdue) {
        detail = "Overdue · Due " + dueText;
      } else if (dueSoon) {
        detail = "Due soon · " + dueText;
      } else {
        detail = "Due " + dueText;
      }

      data.results.push({
        name: rental.getDisplayValue("u_asset") ||
              "Campus resource",
        detail: detail,
        url: "/sp?id=my_rentals"
      });

      shownCount++;

      if (shownCount >= 5) {
        break;
      }
    }

    if (dueOnly) {
      data.reply = shownCount > 0
        ? "Here are your active rentals that are overdue or due within the next two days."
        : "You have no active rentals currently overdue or due within the next two days.";

      if (overdueCount > 0) {
        data.reply += " You have " + overdueCount +
          " overdue rental(s).";
      }

      if (dueSoonCount > 0) {
        data.reply += " You also have " + dueSoonCount +
          " rental(s) due soon.";
      }
    } else {
      data.reply = shownCount > 0
        ? "Here are your active rentals, ordered by due date."
        : "You don't have any active rentals right now.";
    }

    addLink("Open My Rentals", "/sp?id=my_rentals");
  }

  if (!message) {
    data.reply =
      "I can help you find campus resources, check your rentals and due dates, request a renewal, return an item, or report an issue.";
    return;
  }

  // Greetings
  if (/^(hi|hello|hey)\b/.test(message)) {
    data.reply = "Hi " + data.firstName +
      "! What can I help you with today?";

    addLink("Browse assets", "/sp?id=browse_assets");
    addLink("My rentals", "/sp?id=my_rentals");
    addLink("Report an issue", "/sp?id=report_issue");
    return;
  }

  // Issue reporting
  if (
    message.indexOf("report") > -1 ||
    message.indexOf("problem") > -1 ||
    message.indexOf("damaged") > -1 ||
    message.indexOf("broken") > -1 ||
    message.indexOf("malfunction") > -1 ||
    message.indexOf("missing asset") > -1
  ) {
    data.reply =
      "Use the issue-reporting form to report a damaged, missing, or malfunctioning campus resource.";

    addLink("Report an issue", "/sp?id=report_issue");
    return;
  }

  // Renewal guidance
  if (
    message.indexOf("renew") > -1 ||
    message.indexOf("extension") > -1
  ) {
    data.reply =
      "Open Renew an Item to review an active rental and request an extension. Approval depends on your campus renewal workflow.";

    addLink("Renew an item", "/sp?id=renew_asset");
    addLink("My rentals", "/sp?id=my_rentals");
    return;
  }

  // Return guidance
  if (
    message.indexOf("return") > -1 ||
    message.indexOf("give back") > -1
  ) {
    data.reply =
      "Review your active rentals and use the return options to record an item's return.";

    addLink("My rentals", "/sp?id=my_rentals");
    addLink("Return an item", "/sp?id=return_asset");
    return;
  }

  // Due dates and overdue items
  if (
    message.indexOf("due") > -1 ||
    message.indexOf("overdue") > -1 ||
    message.indexOf("deadline") > -1 ||
    message.indexOf("attention") > -1
  ) {
    showRentals(true);
    return;
  }

  // Current student's rentals
  if (
    message.indexOf("my rental") > -1 ||
    message.indexOf("my borrow") > -1 ||
    message.indexOf("borrowed") > -1 ||
    message.indexOf("what have i") > -1
  ) {
    showRentals(false);
    return;
  }

  // Asset search with improved phrase cleanup.
  if (
    message.indexOf("available") > -1 ||
    message.indexOf("find") > -1 ||
    message.indexOf("search") > -1 ||
    message.indexOf("asset") > -1 ||
    message.indexOf("book") > -1 ||
    message.indexOf("laptop") > -1 ||
    message.indexOf("kit") > -1 ||
    message.indexOf("resource") > -1 ||
    message.indexOf("library") > -1 ||
    message.indexOf("location") > -1 ||
    message.indexOf("textbook") > -1 ||
    message.indexOf("operating system") > -1 ||
    message.indexOf("programming") > -1 ||
    message.indexOf("machine learning") > -1
  ) {
    var searchTerm = message
      .replace(/\b(find|search|show|me|please|is|are|the|a|an|do|you|have|has|any|available|availability|campus|resources?|assets?|what|which|can|i|borrow|want|to|get|for|right|now|my)\b/g, " ")
      .replace(/[?!.,]/g, " ")
      .replace(/\s+/g, " ")
      .trim();

    if (
      /^(all|everything|all resources|available resources|available assets|campus resources)$/.test(searchTerm)
    ) {
      searchTerm = "";
    }

    // Match common catalogue names.
    if (searchTerm.indexOf("operating system book") > -1 ||
        searchTerm.indexOf("operating systems book") > -1) {
      searchTerm = "Operating Systems Book";
    } else if (searchTerm.indexOf("programming book") > -1) {
      searchTerm = "Programming Book";
    } else if (searchTerm.indexOf("machine learning") > -1) {
      searchTerm = "Machine Learning";
    } else if (searchTerm.indexOf("laptop") > -1) {
      searchTerm = "Laptop";
    } else if (searchTerm.indexOf("book") > -1) {
      searchTerm = "Book";
    } else if (searchTerm.indexOf("kit") > -1) {
      searchTerm = "Kit";
    }

    showAssets(searchTerm);
    return;
  }

  // Fallback
  data.reply =
    "I can help with finding resources, checking rentals and due dates, requesting a renewal, returning an item, or reporting a problem. Choose an option below.";

  addLink("Browse assets", "/sp?id=browse_assets");
  addLink("My rentals", "/sp?id=my_rentals");
  addLink("Renew an item", "/sp?id=renew_asset");
  addLink("Report an issue", "/sp?id=report_issue");

})();
